create or replace function public.award_xp_for_study_task() returns trigger language plpgsql security definer set search_path=public as $$ begin if new.status = 'completed' then insert into public.xp_events(user_id,source_type,source_id,points) values(new.user_id,'study_task',coalesce(new.node_id,new.id),10) on conflict(user_id,source_type,source_id) do nothing; end if; return new; end; $$;
create or replace function public.award_xp_for_mock_attempt() returns trigger language plpgsql security definer set search_path=public as $$ begin if old.submitted_at is null and new.submitted_at is not null and (coalesce(new.correct,0)+coalesce(new.incorrect,0)) > 0 then insert into public.xp_events(user_id,source_type,source_id,points) values(new.user_id,'mock_test',new.test_id,25) on conflict(user_id,source_type,source_id) do nothing; end if; return new; end; $$;
